function totals(p=S.product){const pc=(p.prints||[]).reduce((s,x)=>s+n(x.filament_cost)+n(x.electricity_cost)+n(x.other_print_cost),0),dc=(p.directCosts||[]).reduce((s,x)=>s+n(x.amount),0),ac=(p.additionalCosts||[]).reduce((s,x)=>s+n(x.amount),0),batch=pc+dc+ac,qty=Math.max(1,parseInt(p.quantity||1)),unit=batch/qty,m=n(p.target_margin),net=unit/(1-m||1),iva=p.iva_enabled?net*n(p.iva_rate):0,gross=net+iva,suggested=commercial(gross,p.round_to),rounded=p.sale_price==null?suggested:Math.max(0,n(p.sale_price)),effectiveNet=p.iva_enabled?rounded/(1+n(p.iva_rate)):rounded,utilityUnit=effectiveNet-unit,utility=utilityUnit*qty,em=effectiveNet?utilityUnit/effectiveNet:0,sales=rounded*qty,finalNet=effectiveNet,finalIva=rounded-effectiveNet;return{suggested,finalNet,finalIva,pc,direct:pc+dc,ac,total:batch,batch,qty,unit,net,iva,rounded,utilityUnit,utility,em,sales}}
