function updatePriceStatus(){const el=q('#priceStatus');if(!el)return;const t=totals();el.className='small '+(t.utilityUnit<0?'loss-text':'');el.textContent='Automático: '+clp(t.suggested)+' · Margen con precio final: '+(t.rounded>0?pct(t.em):'No aplica')+' · Utilidad / un.: '+clp(t.utilityUnit)+(t.utilityUnit<0?' · Este precio genera pérdida.':'')}
function bindV13(){q('#createOrder').onclick=async()=>{if(!canEdit())return;if(S.photoBusy||S.saving)return;if(!S.product.id||S.dirty)await saveProduct();if(S.product.id&&!S.dirty)showNewOrder()};if(!canEdit())return;qa('.filamentSelect').forEach(select=>select.onchange=()=>{const resource=S.resources.find(r=>r.id===select.value);if(!resource)return;const row=select.closest('.filament-row');row.querySelector('.fn').value=resource.name+(resource.material?' · '+resource.material:'');row.querySelector('.fc').value=resource.color;row.querySelector('.fp').value=resource.price_per_kg;refresh()});qa('.printerSelect').forEach(select=>select.onchange=()=>{const el=select.closest('.print-card'),resource=S.resources.find(r=>r.id===select.value);el.querySelector('.printerLabel').value=resource?.name||'';el.querySelector('.printPower').value=resource?.power_kw??'';calcPrintCosts(el)})}
function showDialog(id,html){q('#'+id)?.remove();const dialog=document.createElement('dialog');dialog.id=id;dialog.className='quote-dialog workspace-dialog';dialog.innerHTML=html;document.body.append(dialog);dialog.onclose=()=>dialog.remove();dialog.showModal();dialog.querySelector('[data-close]')?.addEventListener('click',()=>dialog.close());return dialog}
function fieldHtml(label,id,value='',type='text',attrs=''){return '<div class="field"><label for="'+id+'">'+label+'</label><input id="'+id+'" type="'+type+'" value="'+esc(value??'')+'" '+attrs+'></div>'}
function resourcesView(){root.innerHTML=header()+'<main class="shell"><div class="dashboard-head"><div><div class="eyebrow">Configuración compartida</div><h1 class="hero-title">Recursos</h1><p class="muted">Selecciona tus materiales y máquinas al cotizar.</p></div></div>'+(S.err?'<div class="error">'+esc(S.err)+'</div>':'')+['filament','printer'].map(kind=>'<section class="card resource-section"><div class="section-title"><h2>'+(kind==='filament'?'Filamentos':'Impresoras')+'</h2>'+(canEdit()?'<button class="btn btn-primary" data-add-resource="'+kind+'">+ Agregar</button>':'')+'</div><div class="resource-list">'+(S.resources.filter(r=>r.kind===kind).map(r=>'<div class="resource-row '+(!r.active?'inactive':'')+'"><div><b>'+esc(r.name)+'</b><div class="small muted">'+(kind==='filament'?esc(r.material)+' · '+clp(r.price_per_kg)+'/kg':n(r.power_kw)+' kW')+' · '+(r.active?'Disponible':'Inactivo')+'</div></div>'+(canEdit()?'<button class="btn btn-secondary" data-edit-resource="'+r.id+'">Editar</button>':'')+'</div>').join('')||'<p class="muted">Aún no hay '+(kind==='filament'?'filamentos':'impresoras')+' registrados.</p>')+'</div></section>').join('')+'<p class="small muted">Los precios y potencias se copian a la impresión al seleccionarlos. Cambiar el catálogo no modifica productos anteriores.</p></main>';common();qa('[data-add-resource]').forEach(b=>b.onclick=()=>showResourceForm({kind:b.dataset.addResource,active:true}));qa('[data-edit-resource]').forEach(b=>b.onclick=()=>showResourceForm(S.resources.find(r=>r.id===b.dataset.editResource)))}
function showResourceForm(resource){if(!canEdit())return;const isFilament=resource.kind==='filament';const dialog=showDialog('resourceDialog','<div class="section-title"><h2>'+(isFilament?'Filamento':'Impresora')+'</h2><button class="btn btn-ghost" data-close>Volver</button></div><form id="resourceForm" class="grid">'+fieldHtml('Nombre','resourceName',resource.name,'text','required maxlength="160"')+(isFilament?fieldHtml('Marca / material','resourceMaterial',resource.material)+fieldHtml('Color','resourceColor',resource.color||'#303030','color')+fieldHtml('Precio por kilogramo CLP','resourcePrice',resource.price_per_kg??S.settings.filament_price_per_kg,'number','min="0" step="1" required'):fieldHtml('Potencia eléctrica kW','resourcePower',resource.power_kw??S.settings.printer_power_kw,'number','min="0" max="100" step="0.01" required'))+'<label class="small"><input type="checkbox" id="resourceActive" '+(resource.active?'checked':'')+'> Disponible para seleccionar</label><div id="resourceFeedback" role="status" class="small"></div><button class="btn btn-primary" type="submit">Guardar recurso</button></form>');q('#resourceForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter||e.target.querySelector('button[type=submit]');if(b.disabled)return;b.disabled=true;try{const value={workspace_id:S.workspace.id,kind:resource.kind,name:q('#resourceName').value.trim(),active:q('#resourceActive').checked,...(isFilament?{material:q('#resourceMaterial').value.trim(),color:q('#resourceColor').value,price_per_kg:n(q('#resourcePrice').value)}:{power_kw:n(q('#resourcePower').value)})};const query=resource.id?supabase.from('workspace_resources').update(value).eq('id',resource.id).eq('workspace_id',S.workspace.id):supabase.from('workspace_resources').insert(value);const{error}=await query.select().single();if(error)throw error;await loadResources();dialog.close();render()}catch(error){q('#resourceFeedback').textContent=error.message}finally{b.disabled=false}}}
const ORDER_STATUSES={pending:'Pendiente',printing:'Imprimiendo',assembly:'Armado',ready:'Listo',delivered:'Entregado',canceled:'Cancelado'};
function orderNumbers(order){const sales=n(order.quantity)*n(order.unit_price),net=order.iva_enabled?sales/(1+n(order.iva_rate)):sales,actual=order.actual_cost==null?null:n(order.actual_cost)+n(order.failures_cost);return{sales,net,estimatedProfit:net-n(order.estimated_cost),actualCost:actual,actualProfit:actual==null?null:net-actual,variance:actual==null?null:actual-n(order.estimated_cost)}}
function localToday(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function productionView(){const open=S.orders.filter(o=>!['delivered','canceled'].includes(o.status)),late=open.filter(o=>o.due_date&&o.due_date<localToday()),list=S.orders.filter(o=>S.orderFilter==='all'||(S.orderFilter==='open'&&!['delivered','canceled'].includes(o.status))||o.status===S.orderFilter);root.innerHTML=header()+'<main class="shell"><div class="dashboard-head"><div><div class="eyebrow">Pedidos y seguimiento</div><h1 class="hero-title">Producción</h1><p class="muted">Crea pedidos desde el resumen de cada producto.</p></div><button class="btn btn-secondary" id="reloadOrders">Actualizar</button></div>'+(S.err?'<div class="error">'+esc(S.err)+'</div>':'')+'<div class="production-kpis grid grid-2"><div class="metric"><div class="label">Pedidos en curso</div><div class="value">'+open.length+'</div></div><div class="metric"><div class="label">Atrasados</div><div class="value '+(late.length?'loss-text':'')+'">'+late.length+'</div></div></div><div class="field order-filter"><label for="orderFilter">Mostrar pedidos</label><select id="orderFilter"><option value="open">En curso</option><option value="all">Todos</option>'+Object.entries(ORDER_STATUSES).map(([key,label])=>'<option value="'+key+'">'+label+'</option>').join('')+'</select></div><div class="product-list">'+(list.map(o=>{const t=orderNumbers(o);return '<article class="product-card"><div class="row" style="justify-content:space-between"><span class="badge">Pedido #'+o.order_no+'</span><span class="status">'+ORDER_STATUSES[o.status]+'</span></div><h3>'+esc(o.title)+'</h3><p class="muted">'+esc(o.customer_name||'Sin cliente registrado')+' · '+o.quantity+' un.</p><div class="small '+(o.due_date&&o.due_date<localToday()&&!['delivered','canceled'].includes(o.status)?'loss-text':'muted')+'">Entrega: '+(o.due_date?esc(o.due_date.split('-').reverse().join('/')):'Por definir')+'</div><div class="product-stats"><div><span>Venta total</span><b>'+clp(t.sales)+'</b></div><div><span>Costo estimado</span><b>'+clp(o.estimated_cost)+'</b></div></div><div class="small '+(t.actualProfit!=null&&t.actualProfit<0?'loss-text':'muted')+'">'+(t.actualProfit==null?'Costo real pendiente':'Utilidad real: '+clp(t.actualProfit))+'</div><button class="btn btn-secondary" data-order="'+o.id+'">Abrir pedido</button></article>'}).join('')||'<div class="card empty-state"><b>No hay pedidos en esta vista.</b><p class="muted">Abre un producto → Resumen → Crear pedido de producción.</p></div>')+'</div></main>';common();q('#orderFilter').value=S.orderFilter;q('#orderFilter').onchange=e=>{S.orderFilter=e.target.value;productionView()};q('#reloadOrders').onclick=()=>goMode('production');qa('[data-order]').forEach(b=>b.onclick=()=>showOrder(S.orders.find(o=>o.id===b.dataset.order)))}
function showNewOrder(){if(!canEdit()||!S.product?.id)return;const p=S.product,t=totals(),grams=p.prints.reduce((s,x)=>s+n(x.grams),0),minutes=p.prints.reduce((s,x)=>s+n(x.hours)*60+n(x.minutes),0);const dialog=showDialog('newOrderDialog','<div class="section-title"><h2>Nuevo pedido</h2><button class="btn btn-ghost" data-close>Volver</button></div><form id="newOrderForm" class="grid"><b>'+esc(p.name)+'</b>'+fieldHtml('Cliente / referencia','orderCustomer')+'<div class="grid grid-2">'+fieldHtml('Cantidad','orderQty',t.qty,'number','min="1" step="1" required')+fieldHtml('Precio final por unidad','orderPrice',t.rounded,'number','min="0" step="1" required')+fieldHtml('Fecha de entrega','orderDue','','date')+'</div><details class="print-advanced"><summary>Revisar estimación del lote</summary><p class="small muted">Se ajusta proporcionalmente al cambiar la cantidad. Verifica tiempos y costos si imprimes varias piezas en una misma cama.</p><div class="grid grid-2">'+fieldHtml('Costo estimado del lote','orderEstimate',t.total,'number','min="0" step="0.01" required')+fieldHtml('Gramos estimados','orderGrams',grams,'number','min="0" step="0.01"')+fieldHtml('Horas estimadas','orderHours',minutes/60,'number','min="0" step="0.01"')+'</div></details><div class="field"><label for="orderNotes">Notas de producción</label><textarea id="orderNotes"></textarea></div><p class="small muted">Se guardará una copia del precio y la estimación. Cambiar el producto después no altera este pedido.</p><div class="small" id="orderFeedback" role="status"></div><button class="btn btn-primary" type="submit">Confirmar pedido</button></form>');q('#orderQty').oninput=()=>{const ratio=Math.max(1,n(q('#orderQty').value))/t.qty;q('#orderEstimate').value=Math.round(t.total*ratio);q('#orderGrams').value=Math.round(grams*ratio*100)/100;q('#orderHours').value=Math.round(minutes/60*ratio*100)/100};q('#newOrderForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter||e.target.querySelector('button[type=submit]');if(b.disabled)return;b.disabled=true;try{const{error}=await supabase.from('production_orders').insert({workspace_id:S.workspace.id,product_id:p.id,title:p.name,customer_name:q('#orderCustomer').value.trim(),quantity:Math.max(1,Math.floor(n(q('#orderQty').value))),unit_price:n(q('#orderPrice').value),iva_enabled:p.iva_enabled,iva_rate:p.iva_rate,estimated_cost:n(q('#orderEstimate').value),estimated_grams:n(q('#orderGrams').value),estimated_minutes:n(q('#orderHours').value)*60,due_date:q('#orderDue').value||null,notes:q('#orderNotes').value.trim()}).select().single();if(error)throw error;dialog.close();S.orderFilter='open';await goMode('production')}catch(error){q('#orderFeedback').textContent=error.message}finally{b.disabled=false}}}
function showOrder(order){const t=orderNumbers(order);const dialog=showDialog('orderDialog','<div class="section-title"><h2>Pedido #'+order.order_no+'</h2><button class="btn btn-ghost" data-close>Volver</button></div><h3>'+esc(order.title)+'</h3><button class="btn btn-secondary" id="orderQuote">Cotización del pedido</button><p class="muted">'+esc(order.customer_name||'Sin cliente')+' · '+order.quantity+' un. · Venta '+clp(t.sales)+'</p><div class="notice small">Costo estimado: '+clp(order.estimated_cost)+' · '+n(order.estimated_grams)+' g · '+(n(order.estimated_minutes)/60).toFixed(2)+' h<br>Utilidad estimada: '+clp(t.estimatedProfit)+'</div><form id="orderForm" class="grid"><div class="field"><label for="orderStatus">Estado</label><select id="orderStatus">'+Object.entries(ORDER_STATUSES).map(([key,label])=>'<option value="'+key+'">'+label+'</option>').join('')+'</select></div>'+fieldHtml('Entrega','actualDue',order.due_date,'date')+'<p class="small muted">Registra totales reales del lote. El costo base incluye filamento, energía, mano de obra y otros costos; las fallas se suman aparte. Vacío significa pendiente, 0 es un valor registrado.</p><div class="grid grid-2">'+fieldHtml('Costo real base del lote CLP','actualCost',order.actual_cost,'number','min="0" step="0.01"')+fieldHtml('Costo adicional por fallas CLP','failuresCost',order.failures_cost,'number','min="0" step="0.01"')+fieldHtml('Gramos reales (incluida purga)','actualGrams',order.actual_grams,'number','min="0" step="0.01"')+fieldHtml('Horas reales','actualHours',order.actual_minutes==null?'':n(order.actual_minutes)/60,'number','min="0" step="0.01"')+'</div><div id="actualResult" class="notice small" role="status"></div><div class="field"><label for="actualNotes">Notas</label><textarea id="actualNotes">'+esc(order.notes)+'</textarea></div><div id="actualFeedback" class="small" role="status"></div>'+(canEdit()?'<button class="btn btn-primary" type="submit">Guardar avance</button>':'')+'</form>');q('#orderQuote').onclick=()=>showQuote({name:order.title,description:'Pedido #'+order.order_no+(order.customer_name?' · '+order.customer_name:''),photo:null,quantity:order.quantity,price:n(order.unit_price),total:t.sales,net:order.quantity?t.net/order.quantity:0,iva:order.quantity?(t.sales-t.net)/order.quantity:0,ivaEnabled:order.iva_enabled,date:new Date().toLocaleDateString('es-CL')});q('#orderStatus').value=order.status;const getActual=()=>({actual_cost:q('#actualCost').value===''?null:n(q('#actualCost').value),failures_cost:n(q('#failuresCost').value),actual_grams:q('#actualGrams').value===''?null:n(q('#actualGrams').value),actual_minutes:q('#actualHours').value===''?null:n(q('#actualHours').value)*60});const refreshActual=()=>{const result=orderNumbers({...order,...getActual()});q('#actualResult').textContent=result.actualCost==null?'Completa el costo real base para calcular la utilidad.':'Costo real total: '+clp(result.actualCost)+' · Desviación de costo: '+clp(result.variance)+' · Utilidad real: '+clp(result.actualProfit)};refreshActual();if(!canEdit()){dialog.querySelectorAll('form input,form select,form textarea').forEach(el=>el.disabled=true);return}dialog.querySelectorAll('input').forEach(el=>el.oninput=refreshActual);q('#orderForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter||e.target.querySelector('button[type=submit]');if(b.disabled)return;b.disabled=true;try{const{error}=await supabase.from('production_orders').update({...getActual(),status:q('#orderStatus').value,due_date:q('#actualDue').value||null,notes:q('#actualNotes').value.trim(),updated_at:new Date().toISOString()}).eq('id',order.id).eq('workspace_id',S.workspace.id).select().single();if(error)throw error;await loadOrders();dialog.close();productionView()}catch(error){q('#actualFeedback').textContent=error.message}finally{b.disabled=false}}}
function bindV12(){
 q('#quote').onclick=showQuote;
 if(!canEdit())return;
 q('#photoFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;S.photoBusy=true;q('#save').disabled=true;try{const data=await optimizePhoto(file);collect();S.product.photo_data=data;S.dirty=true;render()}catch(error){S.err=error.message;render()}finally{S.photoBusy=false;if(q('#save'))q('#save').disabled=false}};
 q('#removePhoto').onclick=()=>{collect();S.product.photo_data=null;S.dirty=true;render()};
 qa('.dupP').forEach((b,i)=>b.onclick=()=>{collect();S.product.prints.splice(i+1,0,structuredClone(S.product.prints[i]));S.dirty=true;render()});
 qa('.addF').forEach(b=>b.onclick=()=>{collect();const i=qa('.print-card').indexOf(b.closest('.print-card')),p=S.product.prints[i];p.filaments??=[];if(p.filaments.length>=7)return;const first=!p.filaments.length;p.filaments.push({name:first?'Filamento 1':'Filamento '+(p.filaments.length+1),color:'#303030',grams:first?n(p.grams):0,purge_grams:0,price_per_kg:first&&n(p.grams)>0&&n(p.filament_cost)>0?Math.round(n(p.filament_cost)*1000/n(p.grams)):n(S.settings.filament_price_per_kg)});const total=filamentTotals(p.filaments);p.grams=total.grams;p.filament_cost=Math.round(total.cost);S.dirty=true;render()});
 qa('.rmF').forEach(b=>b.onclick=()=>{const card=b.closest('.print-card'),i=qa('.print-card').indexOf(card),j=[...card.querySelectorAll('.filament-row')].indexOf(b.closest('.filament-row'));collect();const p=S.product.prints[i];p.filaments.splice(j,1);const f=filamentTotals(p.filaments);p.grams=f.grams;p.filament_cost=Math.round(f.cost);S.dirty=true;render()});
}
async function optimizePhoto(file){if(!/^image\//.test(file.type)&&!(/\.(heic|heif)$/i.test(file.name)))throw Error('Selecciona una imagen.');if(file.size>20*1024*1024)throw Error('La foto supera 20 MB. Usa una imagen más pequeña.');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const x=new Image();x.onload=()=>resolve(x);x.onerror=()=>reject(Error('No se pudo abrir la foto. Usa JPEG, PNG o WebP.'));x.src=url});const canvas=document.createElement('canvas'),scale=Math.min(1,800/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);for(const quality of [.8,.65,.5,.35]){const data=canvas.toDataURL('image/jpeg',quality);if(validPhoto(data))return data}throw Error('No se pudo optimizar la foto. Prueba una imagen más simple.')}finally{URL.revokeObjectURL(url)}}
function quoteData(){const p=S.product,t=totals(p);return{name:p.name,description:p.description,photo:validPhoto(p.photo_data)?p.photo_data:null,quantity:t.qty,price:t.rounded,total:t.sales,net:t.finalNet,iva:t.finalIva,ivaEnabled:p.iva_enabled,date:new Date().toLocaleDateString('es-CL')}}
function quoteMarkup(d){return '<div class="quote-brand">KULTIVERSO POP</div><p class="muted">Cotización · '+esc(d.date)+'</p>'+productPhoto({photo_data:d.photo,name:d.name},'quote-photo')+'<h2>'+esc(d.name)+'</h2>'+(d.description?'<p class="quote-description">'+esc(d.description)+'</p>':'')+'<table><tr><td>Cantidad</td><td>'+d.quantity+'</td></tr><tr><td>Precio unitario'+(d.ivaEnabled?' (IVA incluido)':'')+'</td><td>'+clp(d.price)+'</td></tr>'+(d.ivaEnabled?'<tr><td>Neto del pedido</td><td>'+clp(d.net*d.quantity)+'</td></tr><tr><td>IVA del pedido</td><td>'+clp(d.iva*d.quantity)+'</td></tr>':'')+'<tr class="quote-total"><td>Total del pedido</td><td>'+clp(d.total)+'</td></tr></table><p class="small muted">Valores en pesos chilenos. Despacho no incluido. Disponibilidad y plazo de producción por confirmar.</p>'}
function showQuote(override=null){const fromOrder=override?.quantity!=null&&override?.price!=null;if(!fromOrder&&canEdit()){collect();persistDraft(false)}const d=fromOrder?override:quoteData();q('#quoteDialog')?.remove();const dialog=document.createElement('dialog');dialog.id='quoteDialog';dialog.className='quote-dialog';dialog.innerHTML='<div class="row quote-toolbar"><button class="btn btn-ghost" id="closeQuote">← Volver</button><button class="btn btn-secondary" id="printQuote">Imprimir / PDF</button><button class="btn btn-primary" id="shareQuote">Compartir imagen</button></div><article id="quoteSheet">'+quoteMarkup(d)+'</article><p id="quoteFeedback" role="status" class="small muted"></p>';document.body.append(dialog);dialog.showModal();q('#closeQuote').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();q('#printQuote').onclick=()=>window.print();q('#shareQuote').onclick=async()=>{const b=q('#shareQuote');b.disabled=true;try{const blob=await quoteImage(d),file=new File([blob],'Cotizacion-Kultiverso-Pop.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({files:[file],title:'Cotización · '+d.name})}else{downloadBlob(blob,'Cotizacion-Kultiverso-Pop.png');q('#quoteFeedback').textContent='Imagen descargada. Puedes adjuntarla en WhatsApp.'}}catch(error){if(error.name!=='AbortError')q('#quoteFeedback').textContent='No se pudo compartir. Usa Imprimir / PDF para guardar la cotización.'}finally{b.disabled=false}}}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function quoteImage(d){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=1000;const wrap=(text,max)=>{const lines=[];for(const para of String(text||'').split('\n')){let line='';for(const word of para.split(/\s+/)){const candidate=line?line+' '+word:word;if(ctx.measureText(candidate).width>max&&line){lines.push(line);line=word}else line=candidate}lines.push(line)}return lines};ctx.font='bold 40px sans-serif';const names=wrap(d.name,880);ctx.font='26px sans-serif';const desc=wrap(d.description,880);canvas.height=630+(d.photo?400:0)+names.length*50+desc.length*35;ctx.fillStyle='#fff';ctx.fillRect(0,0,1000,canvas.height);ctx.fillStyle='#0b0f1f';ctx.fillRect(0,0,1000,120);ctx.fillStyle='#f0a030';ctx.font='bold 36px sans-serif';ctx.fillText('KULTIVERSO POP',60,75);let y=170;ctx.fillStyle='#697183';ctx.font='24px sans-serif';ctx.fillText('Cotización · '+d.date,60,y);y+=35;if(d.photo){const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=d.photo});const scale=Math.min(880/image.width,360/image.height);ctx.drawImage(image,60,y,image.width*scale,image.height*scale);y+=400}ctx.fillStyle='#0b0f1f';ctx.font='bold 40px sans-serif';for(const line of names){ctx.fillText(line,60,y);y+=50}ctx.font='26px sans-serif';for(const line of desc){ctx.fillText(line,60,y);y+=35}y+=30;const row=(label,value)=>{ctx.fillStyle='#697183';ctx.fillText(label,60,y);ctx.fillStyle='#0b0f1f';ctx.textAlign='right';ctx.fillText(value,940,y);ctx.textAlign='left';y+=50};row('Cantidad',String(d.quantity));row('Precio unitario'+(d.ivaEnabled?' (IVA incluido)':''),clp(d.price));if(d.ivaEnabled){row('Neto del pedido',clp(d.net*d.quantity));row('IVA del pedido',clp(d.iva*d.quantity))}ctx.fillStyle='#fff3df';ctx.fillRect(40,y-30,920,80);ctx.font='bold 32px sans-serif';row('Total del pedido',clp(d.total));y+=50;ctx.font='21px sans-serif';ctx.fillStyle='#697183';for(const line of ['Valores en pesos chilenos. Despacho no incluido.','Disponibilidad y plazo de producción por confirmar.']){ctx.fillText(line,60,y);y+=32}return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('No se pudo generar la imagen')),'image/png'))}
